    "questionAr": "أظهر اختبار ديناميكي أن انزلق جسم من السكون إلى أسفل مستوى مائل أملس من ارتفاع رأسي قدره $h = 122.5\\text{ م}$. احسب سرعة وصول الجسم إلى أسفل المستوى ($g = 9.8\\text{ م/ث²}$).",
