    "questionEn": "A bullet is fired horizontally into a uniform wooden block of large thickness. After penetrating a distance of $s_1 = 9\\text{ cm}$, the bullet loses half of its velocity. Assuming the resistance of the wood is constant, find the additional distance the bullet penetrates before coming to rest.",
    "questionAr": "أطلقت رصاصة أفقياً على كتلة خشبية سميكة. فإذا فقدت الرصاصة نصف سرعتها بعد أن غاصت مسافة $s_1 = 9\\text{ سم}$، وبفرض ثبوت مقاومة الخشب، فما هي المسافة الإضافية التي تغوصها الرصاصة حتى تسكن تماماً؟",
