    "correctAnswer": "$54\\text{ km/h} = 15\\text{ m/s}$",
    "correctIndex": 2,
    "hintEn": "Total opposing force is $F = R + mg\\sin\\theta$ in $\\text{kg-wt}$. Maximum speed $v_{\\max} = \\frac{75 P}{F}\\text{ m/s}$.",
    "hintAr": "القوة الكلية المقاومة للحركة صعوداً هي $F = R + mg\\sin\\theta$ بالثقل كجم. أقصى سرعة $v_{\\max} = \\frac{75 P}{F}\\text{ م/ث}$.",
    "stepByStepSolutionEn": [
      "1. Component of weight along incline: $mg\\sin\\theta = 2000 \\times \\frac{1}{20} = 100\\text{ kg-wt}$.",
      "2. Total opposing force: $F = R + mg\\sin\\theta = 20 + 100 = 120\\text{ kg-wt}$.",
      "3. Power formula in horsepower: $P = \\frac{F v_{\\max}}{75} \\implies 24 = \\frac{120 v_{\\max}}{75}$.",
      "4. Solve for $v_{\\max}$: $v_{\\max} = \\frac{75 \\times 24}{120} = \\frac{1800}{120} = 15\\text{ m/s}$.",
      "5. Convert to km/h: $15 \\times \\frac{18}{5} = 54\\text{ km/h}$."
    ],
    "stepByStepSolutionAr": [
      "١. مركبة الوزن في اتجاه خط أكبر ميل: $2000 \\times \\frac{1}{20} = 100\\text{ ث.كجم}$.",
      "٢. القوة المحركة عند أقصى سرعة: $F = R + mg\\sin\\theta = 20 + 100 = 120\\text{ ث.كجم}$.",
      "٣. قانون القدرة بالحصان: $P = \\frac{F v}{75} \\implies 24 = \\frac{120 v}{75}$.",
      "٤. $v = \\frac{75 \\times 24}{120} = 15\\text{ م/ث} = 54\\text{ كم/س}$."
    ],
    "teacherTipEn": "At maximum steady speed, acceleration is zero, so tractive force F exactly balances all resistance and gravity components.",
    "teacherTipAr": "عند أقصى سرعة منتظمة تنعدم العجلة وتتساوى قوة المحرك مع مجموع قوى المقاومة ومركبة الوزن."
