    "questionEn": "A car operating at full engine power can ascend an inclined road of slope $\\sin\\theta = \\frac{1}{10}$ at maximum speed $v_1$, and it can descend the same road at maximum speed $v_2 = 2 v_1$ with the engine operating at the same full power. Assuming constant resistance $R$, find the ratio of resistance to car weight $\\frac{R}{W}$.",
