    "questionAr": "من خلال المشاهدات الحركية، سيارة تعمل بأقصى قدرة لمحركها تستطيع صعود طريق يميل بزاوية $\\sin\\theta = \\frac{1}{80}$ بأقصى سرعة $v_1$، وتستطيع هبوط نفس الطريق بأقصى سرعة $v_2 = 2 v_1$ بنفس القدرة القصوى. بفرض ثبوت المقاومة $R$، أوجد النسبة بين المقاومة ووزن السيارة $\\frac{R}{W}$.",
    "optionsEn": [
      "$\\frac{R}{W} = \\frac{1}{80}$",
      "$\\frac{R}{W} = \\frac{2}{80}$",
      "$\\frac{R}{W} = \\frac{4}{80}$",
      "$\\frac{R}{W} = \\frac{3}{80}$"
    ],
    "optionsAr": [
      "$\\frac{R}{W} = \\frac{1}{80}$",
      "$\\frac{R}{W} = \\frac{2}{80}$",
      "$\\frac{R}{W} = \\frac{4}{80}$",
      "$\\frac{R}{W} = \\frac{3}{80}$"
    ],
    "correctAnswer": "$\\frac{R}{W} = \\frac{3}{80}$",
    "correctIndex": 3,
    "hintEn": "Equate power in both cases: $(R + W\\sin\\theta) v_1 = (R - W\\sin\\theta)(2 v_1)$.",
    "hintAr": "ساوِ القدرة في الحالتين: $(R + W\\sin\\theta) v_1 = (R - W\\sin\\theta)(2 v_1)$.",
    "stepByStepSolutionEn": [
      "1. Uphill power: $P = (R + W \\sin\\theta) v_1$.",
      "2. Downhill power: $P = (R - W \\sin\\theta)(2 v_1)$.",
      "3. Equating: $R + W \\sin\\theta = 2R - 2W \\sin\\theta \\implies R = 3W \\sin\\theta$.",
      "4. Substitute $\\sin\\theta = \\frac{1}{80}$: $\\frac{R}{W} = 3 \\times \\frac{1}{80} = \\frac{3}{80}$."
    ],
    "stepByStepSolutionAr": [
      "١. القدرة صعوداً: $P = (R + W \\sin\\theta) v_1$.",
      "٢. القدرة هبوطاً: $P = (R - W \\sin\\theta)(2 v_1)$.",
      "٣. بمساواة القدرتين: $R + W \\sin\\theta = 2R - 2W \\sin\\theta \\implies R = 3W \\sin\\theta$.",
      "٤. بالتعويض عن $\\sin\\theta = \\frac{1}{80}$: $\\frac{R}{W} = \\frac{3}{80}$."
    ],
    "teacherTipEn": "Notice that when descending at full power, the engine and gravity work together against resistance.",
    "teacherTipAr": "عند الهبوط بأقصى قدرة تعمل قوة المحرك في نفس اتجاه مركبة الوزن ضد المقاومة."
