      "٢. السرعة المشتركة فور التصادم: $v' = \\frac{400 \\times 9.8}{500} = 7.84\\text{ م/ث}$.",
      "٣. طاقة حركة المجموعة لحظة بدء الغوص: $T = \\frac{1}{2}(500)(7.84^2) = 15,366.4\\text{ جول}$.",
      "٤. مبدأ الشغل والطاقة في الأرض: $( (M+m)g - R ) s = -T$.",
      "٥. $(4900 - R)(0.12) = -15,366.4 \\implies R = 4900 + \\frac{15,366.4}{0.12} = 132953\\text{ نيوتن}$."
