    "questionAr": "سيارة كتلتها $m$ بدأت حركتها من السكون وتسارعت بعجلة منتظمة $a$ لمدة زمنية $t_1$. ما نسبة القدرة اللحظية عند اللحظة $t = t_1$ إلى متوسط القدرة خلال الفترة الزمنية $[0, t_1]$؟",
