    "hintAr": "القدرة اللحظية $P(t) = m a^2 t$. ومتوسط القدرة $P_{\\text{avg}} = \\frac{\\frac{1}{2} m v^2}{t_1} = \\frac{1}{2} m a^2 t_1$.",
